/**
 * The types `save/series/` exports. A series itself is typed in `data/charts/types`, shared with
 * the catalog series, so one renderer draws both.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    SaveSeriesExtract
 * depends    src/data/charts/types
 * used by    src/save/series/index, src/save/series/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { ChartSeries } from '../../data/charts/types'

/** The series a save holds, with what could not be read. */
export interface SaveSeriesExtract {
  series: ChartSeries[]
  /** Entries left out of a series, and why: a run with no date, a tournament still in progress. */
  warnings: string[]
}
